import{_ as s,o as t,c as a,a6 as i}from"./chunks/framework.CKIbuWFA.js";const h=JSON.parse('{"title":"Diagnostics et preuves sans secrets","description":"","frontmatter":{"title":"Diagnostics et preuves sans secrets","docId":"developer.diagnostics","translationKey":"developer.diagnostics","locale":"fr","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"bd492eda2007394d29d152e20ec0dba70614f06e6d29b75a3b741ed6b23f11b4","translationRevision":"0dcfd0c5c342e99745938bddfc38d8a97f725aee260d9d7fb91181e96b905453","order":130},"headers":[],"relativePath":"fr/developer/diagnostics.md","filePath":"fr/developer/diagnostics.md","lastUpdated":1794611623000}'),n={name:"fr/developer/diagnostics.md"};function r(o,e,l,d,c,u){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="diagnostics-and-safe-evidence" tabindex="-1">Diagnostics et preuves sans secrets <a class="header-anchor" href="#diagnostics-and-safe-evidence" aria-label="Permalink to &quot;Diagnostics et preuves sans secrets {#diagnostics-and-safe-evidence}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Recueillir assez d’éléments pour localiser un échec sans conserver de secrets de compte ni confondre diagnostics et récupération. Utilisez un hôte de test privé et connaissez le <a href="./transports.html">transport</a> sélectionné. L’application installe un collecteur par session ; les composants d’état y naviguent plutôt que d’ajouter des entrées pendant le rendu.</p><h2 id="inspect-a-failure" tabindex="-1">Examiner un échec <a class="header-anchor" href="#inspect-a-failure" aria-label="Permalink to &quot;Examiner un échec {#inspect-a-failure}&quot;">​</a></h2><ol><li>Ouvrez l’action d’état contextuelle de la connexion, du plugin, de la synchronisation ou du système de mise à jour en échec. Le focus clavier révèle l’action de journal de bureau comme le survol.</li><li>Filtrez par source, gravité et texte, puis examinez le contexte de l’entrée sélectionnée et son nombre de répétitions.</li><li>Copiez les entrées sélectionnées ou filtrées lorsqu’elles expliquent le problème. Examinez les exportations avant de les partager.</li><li>Comparez la santé native à l’observation de l’interface :</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> health</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span></code></pre></div><p>Une sonde LIVE déconnectée peut être ignorée. Une capacité compilée ne prouve pas sa disponibilité à l’exécution. Le panneau d’interface est non modal sur bureau ; les dispositions étroites utilisent <code>/debug</code> avec un emplacement de retour. L’exportation texte native utilise <code>system.saveFile</code> ; les navigateurs téléchargent localement.</p><h2 id="understand-retention" tabindex="-1">Comprendre la rétention <a class="header-anchor" href="#understand-retention" aria-label="Permalink to &quot;Comprendre la rétention {#understand-retention}&quot;">​</a></h2><p><code>src/web/shared/diagnostics/log.ts</code> limite l’historique à 2 000 entrées et 2 Mio d’UTF-8 sérialisé. Les événements consécutifs de même source/entité dans un intervalle de cinq secondes sont regroupés avec un compteur de répétitions. L’expurgation a lieu avant conservation, notamment pour les identifiants reconnus et emplacements de secrets dans les URL ; les secrets tiers arbitraires non étiquetés ne peuvent pas toujours être reconnus. N’ajoutez pas de paramètres bruts, cookies, paramètres RPC ou corps HTTP aux collecteurs.</p><h2 id="expected-result-and-status" tabindex="-1">Résultat attendu et état <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Résultat attendu et état {#expected-result-and-status}&quot;">​</a></h2><p>La visionneuse fournit un historique de session borné et une navigation contextuelle, pas un journal d’audit durable. Le rechargement/démontage efface la mémoire. Effacer l’historique ne supprime pas une erreur de connexion et ne répare pas sa cause. Les identifiants de requêtes Cloud peuvent aider à corréler une enveloppe d’échec sûre ; la couverture des sources suit les collecteurs installés et ne garantit pas la capture de toutes les erreurs du registre ou natives.</p><h2 id="verify-and-recover" tabindex="-1">Vérifier et récupérer <a class="header-anchor" href="#verify-and-recover" aria-label="Permalink to &quot;Vérifier et récupérer {#verify-and-recover}&quot;">​</a></h2><p>Exécutez <code>bun scripts/task.ts test web diagnostics</code> et examinez la <a href="https://github.com/nglmercer/TikTools-app/tree/remake/src/web/shared/diagnostics" target="_blank" rel="noreferrer">source du collecteur</a>. Reproduisez l’expurgation, l’éviction et les répétitions avec des valeurs synthétiques. Pour un conflit, une commande inconnue ou une expiration d’identifiants, revenez au parcours de récupération propriétaire. Copier une entrée diagnostique recueille des preuves ; cela ne réessaie jamais une action et n’approuve pas une nouvelle politique de confiance.</p>`,13)])])}const g=s(n,[["render",r]]);export{h as __pageData,g as default};
